const item = $input.first();
const secret = $env.SHOP_OWNER_WEBHOOK_SECRET;
const headers = item.json.headers || {};
const body = (item.json.body && typeof item.json.body === 'object') ? item.json.body : item.json;
const headerSecret = String(headers['x-shop-webhook-secret'] || headers['X-Shop-Webhook-Secret'] || '');
const bodySecret = String(body.webhookSecret || item.json.webhookSecret || '');
const authorized = !!secret && (headerSecret === secret || bodySecret === secret);
const hasCatalogApiKey = String($env.CATALOG_API_KEY || '').trim().length > 0;

const offerId = body.offerId ? Number(body.offerId) : null;
const productId = body.productId ? Number(body.productId) : null;
const name = String(body.name || '').trim();
const hasPrice = body.price !== undefined && body.price !== null && String(body.price) !== '';
const hasInventory = body.inventory !== undefined && body.inventory !== null && String(body.inventory) !== '';
const price = hasPrice ? Number(body.price) : null;
const inventory = hasInventory ? Number(body.inventory) : null;

let error = '';
let httpStatus = 200;
if (!authorized) { error = 'Unauthorized webhook'; httpStatus = 401; }
else if (!hasCatalogApiKey) { error = 'CATALOG_API_KEY is not set'; httpStatus = 502; }
else if (!offerId && !productId && !name) { error = 'offerId, productId or name is required'; httpStatus = 400; }
else if (!hasPrice && !hasInventory) { error = 'price and/or inventory is required'; httpStatus = 400; }
else if (hasPrice && (!Number.isFinite(price) || price < 0)) { error = 'price must be >= 0'; httpStatus = 400; }
else if (hasInventory && (!Number.isInteger(inventory) || inventory < 0)) { error = 'inventory must be a whole number >= 0'; httpStatus = 400; }

return [{ json: {
  ok: !error, error, httpStatus, offerId, productId, name, price, inventory, hasPrice, hasInventory,
  apiBase: $env.API_BASE_URL || 'http://backend:8080/api',
  siteBase: $env.CONTENT_ADMIN_BASE_URL || 'https://lucaloupe.com'
} }];

const ctx = $input.first().json;
const headers = { 'X-Api-Key': String($env.CATALOG_API_KEY || '') };
const api = ctx.apiBase;

const unwrap = (res) => {
  if (Array.isArray(res)) return res;
  if (Array.isArray(res?.data)) return res.data;
  if (Array.isArray(res?.data?.records)) return res.data.records;
  return res?.data ?? res;
};

const http = async (method, url, body) => {
  const opts = { method, url, headers, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true };
  if (body !== undefined) {
    opts.body = body;
    opts.headers = { ...headers, 'Content-Type': 'application/json' };
  }
  const res = await this.helpers.httpRequest(opts);
  const status = res.statusCode || res.status || 200;
  const payload = res.body !== undefined ? res.body : res;
  if (status >= 400) {
    const err = payload?.error || payload?.title || payload?.message || `HTTP ${status}`;
    const e = new Error(String(err));
    e.statusCode = status;
    throw e;
  }
  return payload;
};

try {
  let productId = ctx.productId;
  let offerId = ctx.offerId;
  let productName = ctx.name;

  if (!productId && !offerId && ctx.name) {
    const search = await http('GET', `${api}/Products/search?keyword=${encodeURIComponent(ctx.name)}`);
    const products = unwrap(search) || [];
    const list = Array.isArray(products) ? products : [];
    if (list.length === 0) {
      return [{ json: { ok: false, httpStatus: 404, error: `No product matched: ${ctx.name}` } }];
    }
    if (list.length > 1) {
      const candidates = list.slice(0, 8).map(p => ({ id: p.id, name: p.name }));
      return [{ json: { ok: false, httpStatus: 409, error: 'Multiple products matched; pass productId', candidates } }];
    }
    productId = list[0].id;
    productName = list[0].name;
  }

  if (!offerId) {
    if (!productId) {
      return [{ json: { ok: false, httpStatus: 400, error: 'Could not resolve product' } }];
    }
    const offerRes = await http('GET', `${api}/ProductOffers/by-product/${productId}`);
    const offers = unwrap(offerRes) || [];
    const list = Array.isArray(offers) ? offers : [];
    if (list.length === 0) {
      return [{ json: { ok: false, httpStatus: 404, error: `No offer for productId ${productId}` } }];
    }
    if (list.length > 1) {
      const candidates = list.map(o => ({ id: o.id, productId: o.productId, productName: o.productName, price: o.basePrice, inventory: o.inventory }));
      return [{ json: { ok: false, httpStatus: 409, error: 'Multiple offers; pass offerId', candidates } }];
    }
    offerId = list[0].id;
    productName = productName || list[0].productName;
    productId = productId || list[0].productId;
  }

  const payload = { id: offerId };
  if (ctx.hasPrice) payload.basePrice = ctx.price;
  if (ctx.hasInventory) payload.inventory = ctx.inventory;

  const updated = await http('PUT', `${api}/ProductOffers`, payload);
  if (updated?.isSuccess === false) {
    return [{ json: { ok: false, httpStatus: updated.error === 'Unauthorized' ? 401 : 400, error: updated.error || 'Update offer failed' } }];
  }

  const url = `${String(ctx.siteBase).replace(/\/$/, '')}/fa/products/${productId}`;
  const inventory = ctx.hasInventory ? ctx.inventory : undefined;
  const lowStock = ctx.hasInventory && Number.isFinite(inventory) && inventory < 2;
  return [{ json: {
    ok: true, httpStatus: 200, offerId, productId, name: productName,
    price: ctx.hasPrice ? ctx.price : undefined,
    inventory,
    lowStock,
    telegramChatId: String($env.TELEGRAM_CHAT_ID || '').trim(),
    url
  } }];
} catch (e) {
  const msg = e.message || String(e);
  const status = e.statusCode || 502;
  return [{ json: { ok: false, httpStatus: status >= 400 ? status : 502, error: msg } }];
}

const upd = $('Update Offer').item.json;
return [{ json: {
  ok: true, httpStatus: 200, offerId: upd.offerId, productId: upd.productId, name: upd.name,
  price: upd.price, inventory: upd.inventory, url: upd.url, lowStockAlerted: true
} }];

